// Pivot step 1 (D158): order of Frobenius on each level-one mod-2 target
// system at one prime of F above the rational prime PRIME.
//
// Usage (one fresh Magma per rational prime):
//   HMF_ROOT=/path/to/hilbertmodularforms PRIME=127 \
//     magma -b dembele/pivot/01_frobenius_order_scan.m
//
// The two systems are labelled by the T31 trace polynomials at the prime
// generated by g31 (as in magma/11_hecke_fingerprints.m):
//   a: t^8+t^4+t^3+t+1      b: t^8+t^6+t^5+t^2+1
// Output: one RESULT line per prime above PRIME (or only the first if
// ALLPRIMES is unset), giving the order of rho(Frob) for each system.
// The extension degree needed for the torsion to be rational over the
// residue field of that prime is exactly that order.

hmf_root := GetEnv("HMF_ROOT");
AttachSpec(hmf_root cat "/spec");
p := StringToInteger(GetEnv("PRIME"));
allprimes := GetEnv("ALLPRIMES") ne "";

Qx<x> := PolynomialRing(Rationals());
F<beta> := NumberField(x^8 - 8*x^6 + 20*x^4 - 16*x^2 + 2);
OF := Integers(F);
M := HilbertCuspForms(F, 1*OF, [2 : i in [1..8]]);
g31 := F![1, 2, 0, -4, 0, 1, 0, 0];
p31 := ideal<OF | OF!g31>;

mod2 := function(T)
    return Matrix(GF(2), Nrows(T), Ncols(T), [Integers()!e : e in Eltseq(T)]);
end function;

T31 := mod2(InternalHMFRawHeckeDefinite(M, p31));
F2t<t> := PolynomialRing(GF(2));
ha := t^8 + t^4 + t^3 + t + 1;
hb := t^8 + t^6 + t^5 + t^2 + 1;
Va := Kernel(Evaluate(ha, T31));
Vb := Kernel(Evaluate(hb, T31));
assert Dimension(Va) eq 8 and Dimension(Vb) eq 8;

frob_order := function(V, T)
    B := BasisMatrix(V);
    A := Solution(B, B*T);          // action of T on V in the basis B
    m := MinimalPolynomial(A);
    fac := Factorization(m);
    assert #fac eq 1 and fac[1][2] eq 1;   // a_P is a single element of F256
    K := GF(2^Degree(fac[1][1]));
    a := Roots(fac[1][1], K)[1][1];
    if a eq 0 then
        return 2, m;                // trace 0: unipotent, order divides 2
    end if;
    L := GF(2^16);
    Ly<y> := PolynomialRing(L);
    r := Roots(y^2 + L!a*y + 1)[1][1];
    return Order(r), m;
end function;

primes := [pp[1] : pp in Factorization(p*OF)];
if not allprimes then primes := [primes[1]]; end if;
for i in [1..#primes] do
    P := primes[i];
    t0 := Cputime();
    TP := mod2(InternalHMFRawHeckeDefinite(M, P));
    assert T31*TP eq TP*T31;
    oa, ma := frob_order(Va, TP);
    ob, mb := frob_order(Vb, TP);
    _, gen := IsPrincipal(P);
    printf "RESULT|p=%o|index=%o|norm=%o|gen=%o|order_a=%o|order_b=%o|min_a=%o|min_b=%o|cpu=%o\n",
        p, i, Norm(P), Eltseq(F!gen), oa, ob, ma, mb, Cputime(t0);
end for;
printf "DONE|p=%o\n", p;
quit;
